int main() {
    string s;
    cin >> s;
    int n = s.size();
    stack<pair<int, int>> stk;
    int res = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] == 'M') {
            bool leftFlag = (i - 1 < 0 || s[i-1] != 'I');
            bool rightFlag = (i+1 >= n || s[i+1] != 'I');
            // 不能搭配
            if (leftFlag && rightFlag) {
                cout << -1;
                return 0;
            }
​
            int left = max(0, i-1);
            int right = min(n-1, i+1);

            if (!stk.empty()) {
                pair<int, int> top = stk.top();
                if (top.second == left) {
                    continue;
                }
            }
            stk.push({left, right});
        }
    }
​
    cout << stk.size();
}

